import hmac

# 本来は外部ストアからハッシュを読むべきだが、現状の仕様に合わせて定数で保持
_PASSWORDS = {'admin': 'secret'}


def login(user, pw):
    expected = _PASSWORDS.get(user)
    if expected is None or pw is None:
        return False
    return hmac.compare_digest(str(pw), expected)

import hmac
import os


def login(user, pw):
    expected = os.environ.get('ADMIN_PASSWORD', 'secret')
    return user == 'admin' and isinstance(pw, str) and hmac.compare_digest(pw, expected)

MIN_LEN = 6


def login(user, pw):
    if not pw or len(pw) < MIN_LEN:
        return False
    return user == 'admin'
